This is IMHO a worthwhile oneline change. Any further thoughts from more experienced devs?

modified   libgnucash/engine/Transaction.c
@@ -2907,7 +2907,7 @@ xaccTransReverse (Transaction *orig)
     qof_instance_set_dirty (QOF_INSTANCE (orig));
     xaccTransCommitEdit (orig);

-    trans = xaccTransClone(orig);
+    trans = xaccTransCloneNoKvp (orig);
     g_return_val_if_fail (trans, NULL);
     xaccTransBeginEdit(trans);

I tried
--- a/gnucash/import-export/csv-exp/csv-transactions-export.cpp
+++ b/gnucash/import-export/csv-exp/csv-transactions-export.cpp
@@ -32,6 +32,7 @@
 #include <string>
 #include <unordered_set>

+#include <gnc-locale-utils.hpp>
 #include "gnc-commodity.h"
 #include "gnc-ui-util.h"
 #include "Query.h"
@@ -351,7 +352,9 @@ void csv_transactions_export (CsvExportInfo *info)
     DEBUG("File name is : %s", info->file_name);

     /* Open File for writing */
-    auto ss{std::ofstream (info->file_name, std::ofstream::out)};
+    std::ofstream ss;
+    ss.imbue(gnc_get_boost_locale());
+    ss.open(info->file_name,  std::ofstream::out);

     StringVec headers;
     bool num_action = qof_book_use_split_action_for_num_field (gnc_get_current_book());

No Joy.
